// === Tab: mySketch ===
// strokeShaderとfillShaderとpointShaderをすべて使う実験
// fillShaderで回転する立方体を描画し
// strokeShaderでそのまわりに線をぐるぐるさせ
// さらにパーティクルをたくさん飛び回らせる感じ
// 軌道は線を摂動させる感じ
// 総復習って感じね

// テキストで説明付けつつ正二十面体ダイス
// パーティクルのテクスチャ貼り付けで方向情報付与で矢印ぎゅーん
// テクスチャを用いた位置指示
// テキストシェーダのカスタム
// やりたいことはいっぱいある

// その前にライティングを何とかするね・・
// まあ、普通にやってもいいかな・・って気がしてきた（
// やー、やっぱ自己流危険だわ。いちから組みなおそう。

// というわけで今回はfillShaderに特化しますね

// 裏側描画できたー
// maxのとこ（ランベルト）が0.0だからか
// ここを0.3とかにするとよい

// 頂点色できたね

// フォンも気になるねやっぱり

// 今まで通りでいい気がしてきたからダメ

// よし。

let gl;

let myFillShader;
let myStrokeShader;
let myPointShader;
let pointBuf; // pointSpriteのバッファにアクセスできないといけない
// じゃないと_drawPointsが使えないので
let count = 0;

let vsFill =
"precision highp float;" +
"attribute vec3 aPosition;" +
"attribute vec4 aMaterialColor;" +
"attribute vec3 aNormal;" +

"uniform mat4 uModelViewMatrix;" +
"uniform mat4 uProjectionMatrix;" +
"uniform mat3 uNormalMatrix;" +

"uniform vec3 uLightingDirection[5];" +
"uniform vec3 uDirectionalDiffuseColors[5];" +

"varying vec4 vVertexColor;" +
"varying vec3 vNormal;" +
"varying vec3 vLightDirection;" +
"varying vec3 vDirectionalDiffuseColor;" +

"void main(){" +
"  vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);" +
"  gl_Position = uProjectionMatrix * viewModelPosition;" +
"  vVertexColor = aMaterialColor;" +

"  vNormal = normalize(uNormalMatrix * aNormal);" +
"  vLightDirection = -uLightingDirection[0];" +
"  vDirectionalDiffuseColor = uDirectionalDiffuseColors[0];" +
"}";

let fsFill =
"precision highp float;" +

"varying vec4 vVertexColor;" +
"varying vec3 vNormal;" +
"varying vec3 vLightDirection;" +
"varying vec3 vDirectionalDiffuseColor;" +

"uniform vec4 uTint;" +

"void main(){" +
"  vec4 col = vVertexColor;" +
"  col *= uTint;" +
"  col.rgb = mix(col.rgb, vDirectionalDiffuseColor, 0.5);" +
"  col *= max(0.5, dot(vNormal, vLightDirection));" +
"  gl_FragColor = col;" +
"}";

let vsStroke =
`
precision highp float;
precision highp int;
/*
